import { test, expect } from '@playwright/test';

test.describe('Language Preference Setting in Profile Settings', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/profile/settings');
  });

  test('should successfully set language preference and update UI', async ({ page }) => {
    // Verify profile settings page loads
    const settingsHeader = page.getByRole('heading', { name: /profile settings/i });
    await expect(settingsHeader).toBeVisible();

    // Verify language dropdown is visible and has default value
    const languageSelect = page.getByLabel(/language/i);
    await expect(languageSelect).toBeVisible();
    await expect(languageSelect).toHaveValue('en-US');

    // Set language to Spanish
    await languageSelect.selectOption('es-ES');

    // Verify language selection is updated in dropdown
    await expect(languageSelect).toHaveValue('es-ES');

    // Click save button
    const saveButton = page.getByRole('button', { name: /save/i });
    await saveButton.click();

    // Verify success message appears
    const successMessage = page.getByText(/language preference updated successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify language dropdown reflects the new selection
    await expect(languageSelect).toHaveValue('es-ES');

    // Verify page content is displayed in Spanish
    const welcomeMessage = page.getByText(/bienvenido/i);
    await expect(welcomeMessage).toBeVisible();
  });

  test('should handle invalid language selection and display error message', async ({ page }) => {
    // Verify profile settings page loads
    const settingsHeader = page.getByRole('heading', { name: /profile settings/i });
    await expect(settingsHeader).toBeVisible();

    // Set language to invalid option
    const languageSelect = page.getByLabel(/language/i);
    await languageSelect.selectOption('invalid-lang');

    // Click save button
    const saveButton = page.getByRole('button', { name: /save/i });
    await saveButton.click();

    // Verify error message appears
    const errorMessage = page.getByText(/invalid language selection/i);
    await expect(errorMessage).toBeVisible();

    // Verify language dropdown did not change
    await expect(languageSelect).toHaveValue('en-US');

    // Verify success message does not appear
    const successMessage = page.getByText(/language preference updated successfully/i);
    await expect(successMessage).not.toBeVisible();

    // Verify page content remains in English
    const welcomeMessage = page.getByText(/welcome/i);
    await expect(welcomeMessage).toBeVisible();
  });
});
